import { readFile, writeFile } from 'node:fs/promises';
const migrations = [
  '001_existing_thermal_alerts.sql',
  '002_mobile_operations.sql',
  '003_offline_alert_order.sql',
  '004_operational_reliability.sql',
  '005_closed_trip_alerts.sql',
];
let sql =
  '-- Koda mobile: apply once to the SAME Supabase database used by the web.\n-- Generated by npm run server:sql. Does not include the reference schema.\n-- Requires the existing Koda tables. Every change is in one transaction.\nBEGIN;\n';
for (const name of migrations) {
  const source = await readFile(new URL(`../server/migrations/${name}`, import.meta.url), 'utf8');
  sql += `\n-- ${name}\n${source.replace(/^BEGIN;\s*$/gm, '').replace(/^COMMIT;\s*$/gm, '')}\n`;
}
sql += "\nNOTIFY pgrst, 'reload schema';\nCOMMIT;\n";
await writeFile(new URL('../server/supabase-setup.sql', import.meta.url), sql);
console.log('SQL de instalação pronto: server/supabase-setup.sql');
